// 火鸟门户内容处理核心模块集成
const { HuoNiaoContentProcessor } = require('./火鸟门户_内容处理核心模块.js');

// 初始化内容处理器
const processor = new HuoNiaoContentProcessor({
  aiApiKey: process.env.OPENAI_API_KEY,
  enableCache: true,
  enableLogging: true,
  similarityThreshold: 0.8,
  minContentLength: 100,
  maxContentLength: 5000,
  minTitleLength: 5,
  maxTitleLength: 60
});

// 获取输入数据
const inputData = $input.first().json;

// 数据预处理
const preprocessedData = {
  title: inputData.title || '',
  content: inputData.content || inputData.description || '',
  category: inputData.category || '',
  author: inputData.author || 'AI采集',
  source: inputData.source || 'API采集',
  source_url: inputData.url || inputData.source_url || '',
  image_url: inputData.urlToImage || inputData.image_url || '',
  keywords: inputData.keywords || '',
  summary: inputData.summary || inputData.description || '',
  publishedAt: inputData.publishedAt || new Date().toISOString(),
  images: inputData.images || (inputData.urlToImage ? [inputData.urlToImage] : [])
};

try {
  // 处理内容
  const result = await processor.processContent(preprocessedData, {
    enableAI: true,
    optimizeTitle: true,
    optimizeContent: true,
    generateKeywords: true,
    generateSummary: true,
    strictMode: false
  });

  if (!result.success) {
    if (result.isDuplicate) {
      return {
        json: {
          status: 'skipped',
          reason: 'duplicate_content',
          message: '检测到重复内容，跳过处理',
          duplicateInfo: result.duplicateInfo
        }
      };
    }
    throw new Error(result.error || '内容处理失败');
  }

  // 返回处理后的数据
  return {
    json: {
      status: 'processed',
      data: result.data,
      metadata: result.metadata,
      originalData: inputData
    }
  };

} catch (error) {
  console.error('内容处理失败:', error);
  return {
    json: {
      status: 'error',
      error: error.message,
      originalData: inputData
    }
  };
}

