// 数据预处理和验证
const inputData = $input.all();
const processedItems = [];

for (const item of inputData) {
  const data = item.json.data;

  // 基础数据验证
  if (!data.title || !data.content) {
    throw new Error('缺少必要字段: title 或 content');
  }

  // 数据清洗和标准化
  const processedData = {
    title: data.title.trim().substring(0, 60),
    content: data.content,
    category: data.category || '新闻',
    author: data.author || 'AI采集',
    source: data.source || 'API采集',
    image_url: data.image_url || '',
    publish_date: data.publish_date || new Date().toISOString(),
    tags: data.keywords || '',
    description: data.summary || '',
    source_url: data.source_url || '',
    priority: data.priority || 0,
    status: data.status || 0,
    custom_fields: data.custom_fields || {}
  };

  // 生成去重键
  processedData.dedupe_key = `${processedData.title}_${processedData.source}`;

  // 添加时间戳和请求ID
  processedData.timestamp = Date.now();
  processedData.request_id = `req_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

  processedItems.push({ json: processedData });
}

return processedItems;

// 生成HMAC-SHA256签名
const crypto = require('crypto');
const secretKey = 'huoniao_gateway_secret_2025'; // 应该从环境变量获取

const inputData = $input.all();
const results = [];

for (const item of inputData) {
  const data = item.json;
  const timestamp = Math.floor(Date.now() / 1000);

  // 构建签名字符串
  const signatureString = `POST|/v1/articles|${timestamp}|${JSON.stringify(data)}`;

  // 生成签名
  const signature = crypto
    .createHmac('sha256', secretKey)
    .update(signatureString)
    .digest('hex');

  results.push({
    json: {
      ...data,
      signature: signature,
      timestamp: timestamp
    }
  });
}

return results;

// 成功处理
const inputData = $input.all();
const results = [];

for (const item of inputData) {
  const data = item.json;

  results.push({
    json: {
      status: 'success',
      article_id: data.data?.id || data.id,
      title: data.data?.title || data.title,
      message: data.message || '文章发布成功',
      request_id: data.request_id,
      timestamp: new Date().toISOString(),
      processing_time: Date.now() - data.timestamp
    }
  });
}

return results;

// 错误处理
const inputData = $input.all();
const results = [];

for (const item of inputData) {
  const data = item.json;
  const error = data.error || {};

  // 判断错误类型
  let shouldRetry = false;
  let retryDelay = 0;

  if (error.code === 'RATE_LIMIT_ERROR') {
    shouldRetry = true;
    retryDelay = 30000; // 30秒后重试
  } else if (error.code === 'SESSION_ERROR') {
    shouldRetry = true;
    retryDelay = 5000; // 5秒后重试
  } else if (error.code === 'NETWORK_ERROR') {
    shouldRetry = true;
    retryDelay = 10000; // 10秒后重试
  }

  results.push({
    json: {
      status: 'error',
      error_code: error.code || 'UNKNOWN_ERROR',
      error_message: error.message || data.message || '未知错误',
      error_type: error.type || 'system',
      request_id: data.request_id,
      timestamp: new Date().toISOString(),
      processing_time: Date.now() - data.timestamp,
      should_retry: shouldRetry,
      retry_delay: retryDelay,
      original_data: data
    }
  });
}

return results;

