// 批量处理节点
const { HuoNiaoContentProcessor } = require('./火鸟门户_内容处理核心模块.js');
const { HuoNiaoAPIGateway } = require('./火鸟门户_API集成模块.js');

// 初始化处理器和网关
const processor = new HuoNiaoContentProcessor({
  aiApiKey: process.env.OPENAI_API_KEY,
  enableCache: true,
  enableLogging: true,
  similarityThreshold: 0.8
});

const gateway = new HuoNiaoAPIGateway({
  baseUrl: process.env.HUONIAO_BASE_URL || 'https://hawaiihub.net',
  adminPath: process.env.HUONIAO_ADMIN_PATH || '/admin',
  username: process.env.HUONIAO_USERNAME,
  password: process.env.HUONIAO_PASSWORD,
  enableRateLimit: true,
  enableRetry: true
});

// 获取批量数据
const batchData = $input.all().map(item => item.json);

try {
  // 批量处理内容
  const processingResult = await processor.batchProcessContent(batchData, {
    batchSize: 5,
    delayBetweenBatches: 2000,
    enableAI: true,
    optimizeTitle: true,
    optimizeContent: true,
    generateKeywords: true,
    generateSummary: true
  });

  // 提取成功处理的内容
  const successfulContent = processingResult.results
    .filter(result => result.success && !result.isDuplicate)
    .map(result => result.data);

  if (successfulContent.length === 0) {
    return {
      json: {
        status: 'no_content',
        message: '没有可发布的内容',
        summary: processingResult.summary
      }
    };
  }

  // 批量发布到火鸟
  const publishResults = [];

  for (const content of successfulContent) {
    try {
      // 转换为火鸟格式
      const articleData = {
        title: content.title,
        typeid: content.categoryId || 1,
        body: content.content,
        writer: content.author,
        source: content.source,
        keywords: content.keywords,
        description: content.summary,
        litpic: content.image_url || ''
      };

      // 发布文章
      const publishResult = await gateway.publishArticle(articleData, {
        enableDedupe: true,
        validateData: true
      });

      publishResults.push({
        success: true,
        articleId: publishResult.articleId,
        title: content.title
      });

      // 批次间延迟
      await new Promise(resolve => setTimeout(resolve, 1000));

    } catch (error) {
      publishResults.push({
        success: false,
        error: error.message,
        title: content.title
      });
    }
  }

  const summary = {
    totalProcessed: batchData.length,
    contentProcessed: processingResult.summary.success,
    contentFailed: processingResult.summary.failed,
    contentDuplicates: processingResult.summary.duplicates,
    articlesPublished: publishResults.filter(r => r.success).length,
    articlesFailed: publishResults.filter(r => !r.success).length
  };

  return {
    json: {
      status: 'batch_completed',
      summary,
      publishResults,
      processingResult: processingResult.summary
    }
  };

} catch (error) {
  console.error('批量处理失败:', error);
  return {
    json: {
      status: 'batch_failed',
      error: error.message,
      totalItems: batchData.length
    }
  };
}

// 监控和统计节点
const stats = {
  timestamp: new Date().toISOString(),
  workflow: 'huoniao-news-collection',
  version: '2.0.0'
};

// 收集所有输入数据进行统计
const allInputs = $input.all();
const results = allInputs.map(item => item.json);

// 统计各种状态
stats.total = results.length;
stats.published = results.filter(r => r.status === 'published').length;
stats.failed = results.filter(r => r.status === 'failed').length;
stats.duplicates = results.filter(r => r.status === 'duplicate').length;
stats.skipped = results.filter(r => r.status === 'skipped').length;
stats.processing_failed = results.filter(r => r.status === 'processing_failed').length;

// 计算成功率
stats.successRate = stats.total > 0 ? (stats.published / stats.total * 100).toFixed(2) + '%' : '0%';

// 质量分析
const publishedArticles = results.filter(r => r.status === 'published');
if (publishedArticles.length > 0) {
  const qualityScores = publishedArticles
    .map(r => r.originalData?.qualityScore || 0)
    .filter(score => score > 0);

  if (qualityScores.length > 0) {
    stats.avgQualityScore = (qualityScores.reduce((a, b) => a + b, 0) / qualityScores.length).toFixed(2);
    stats.minQualityScore = Math.min(...qualityScores);
    stats.maxQualityScore = Math.max(...qualityScores);
  }
}

// 分类统计
const categories = {};
publishedArticles.forEach(article => {
  const category = article.originalData?.category || 'Unknown';
  categories[category] = (categories[category] || 0) + 1;
});
stats.categoryDistribution = categories;

// 错误分析
const errors = results
  .filter(r => r.status === 'failed' || r.status === 'processing_failed')
  .map(r => r.error)
  .filter(error => error);

const errorCounts = {};
errors.forEach(error => {
  const errorType = error.split(':')[0] || error;
  errorCounts[errorType] = (errorCounts[errorType] || 0) + 1;
});
stats.errorDistribution = errorCounts;

// 性能统计
const processingTimes = results
  .filter(r => r.processingTime)
  .map(r => r.processingTime);

if (processingTimes.length > 0) {
  stats.avgProcessingTime = (processingTimes.reduce((a, b) => a + b, 0) / processingTimes.length).toFixed(2) + 'ms';
  stats.minProcessingTime = Math.min(...processingTimes) + 'ms';
  stats.maxProcessingTime = Math.max(...processingTimes) + 'ms';
}

console.log('工作流统计报告:', JSON.stringify(stats, null, 2));

return {
  json: {
    ...stats,
    message: '统计报告生成完成',
    details: results
  }
};

// 健康检查节点
const { HuoNiaoAPIGateway } = require('./火鸟门户_API集成模块.js');

// 初始化网关
const gateway = new HuoNiaoAPIGateway({
  baseUrl: process.env.HUONIAO_BASE_URL || 'https://hawaiihub.net',
  adminPath: process.env.HUONIAO_ADMIN_PATH || '/admin',
  username: process.env.HUONIAO_USERNAME,
  password: process.env.HUONIAO_PASSWORD
});

try {
  // 检查系统健康状态
  const healthCheck = await gateway.healthCheck();

  const status = {
    timestamp: new Date().toISOString(),
    system: 'huoniao-news-gateway',
    status: 'healthy',
    checks: {
      apiConnection: healthCheck.apiAvailable,
      authentication: healthCheck.authValid,
      database: healthCheck.dbConnected,
      sessionValid: healthCheck.sessionValid
    },
    performance: {
      responseTime: healthCheck.responseTime,
      memoryUsage: process.memoryUsage(),
      uptime: process.uptime()
    }
  };

  // 检查是否有任何问题
  const hasIssues = Object.values(status.checks).some(check => !check);
  if (hasIssues) {
    status.status = 'degraded';
    status.issues = Object.entries(status.checks)
      .filter(([key, value]) => !value)
      .map(([key]) => key);
  }

  console.log('系统健康检查:', JSON.stringify(status, null, 2));

  return {
    json: status
  };

} catch (error) {
  const errorStatus = {
    timestamp: new Date().toISOString(),
    system: 'huoniao-news-gateway',
    status: 'unhealthy',
    error: error.message,
    checks: {
      apiConnection: false,
      authentication: false,
      database: false,
      sessionValid: false
    }
  };

  console.error('系统健康检查失败:', JSON.stringify(errorStatus, null, 2));

  return {
    json: errorStatus
  };
}
